const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pt=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}),int=new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1});
const reais=n=>pt.format(Number(n)||0),fmt=n=>int.format(Number(n)||0),today=()=>new Date().toISOString().slice(0,10),dbr=d=>d?new Date(String(d).slice(0,10)+'T12:00:00').toLocaleDateString('pt-BR'):'—';
const ico=(name)=>{const shapes={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',hardhat:'<path d="M2 18v-2h20v2a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2ZM5 16V9a7 7 0 0 1 14 0v7M12 3v8"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',database:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 1.65 4 3 9 3s9-1.35 9-3V5M3 12c0 1.65 4 3 9 3s9-1.35 9-3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',chart:'<path d="M3 3v18h18M7 15v3M12 10v8M17 6v12"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06-2.8 2.8-.07-.06a1.65 1.65 0 0 0-1.81-.33 1.65 1.65 0 0 0-1 1.52V21h-4v-.09a1.65 1.65 0 0 0-1-1.52 1.65 1.65 0 0 0-1.81.33l-.07.06-2.8-2.8.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.52-1H3v-4h.09a1.65 1.65 0 0 0 1.52-1 1.65 1.65 0 0 0-.33-1.81l-.06-.07 2.8-2.8.07.06a1.65 1.65 0 0 0 1.81.33 1.65 1.65 0 0 0 1-1.52V3h4v.09a1.65 1.65 0 0 0 1 1.52 1.65 1.65 0 0 0 1.81-.33l.07-.06 2.8 2.8-.06.07a1.65 1.65 0 0 0-.33 1.81 1.65 1.65 0 0 0 1.52 1H21v4h-.09a1.65 1.65 0 0 0-1.52 1Z"/>',search:'<circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>',plus:'<path d="M12 5v14M5 12h14"/>',moon:'<path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/>',monitor:'<rect x="2" y="3" width="20" height="15" rx="2"/><path d="M8 21h8M12 18v3"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',chevron:'<path d="m6 9 6 6 6-6"/>',right:'<path d="M5 12h14m-6-6 6 6-6 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',logout:'<path d="M10 17l5-5-5-5M15 12H3M12 3h6a3 3 0 0 1 3 3v12a3 3 0 0 1-3 3h-6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6M10 10v7m4-7v7"/>',edit:'<path d="M12 20h9M16.5 3.5a2.1 2.1 0 0 1 3 3L9 17l-4 1 1-4Z"/>',filter:'<path d="M4 4h16l-6.5 7.5V20l-3-2v-6.5Z"/>',print:'<path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2M6 14h12v8H6z"/>',send:'<path d="m22 2-7 20-4-9-9-4Z"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',building:'<rect x="3" y="2" width="18" height="20" rx="1"/><path d="M9 22v-6h6v6M7 6h.01M12 6h.01M17 6h.01M7 11h.01M12 11h.01M17 11h.01"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};return `<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">${shapes[name]||shapes.file}</svg>`};
const NAV=[['dashboard','Dashboard','home'],['clientes','Clientes','users'],['obras','Obras','hardhat'],['orcamentos','Orçamentos','file'],['siurb','Composições SIURB','database'],['cronograma','Cronogramas','calendar'],['propostas','Propostas PDF','file'],['relatorios','Relatórios','chart'],['configuracoes','Configurações','settings']];
const ST={ready:false,auth:{},clients:[],projects:[],budgets:[],catalog:[],proposals:[],settings:{},dash:null,page:'dashboard',budget:null,search:'',modal:'',themeMenu:false,menu:false,tab:'itens',scheduleBudget:0,proposalBudget:0};
const sel=(val,arr,placeholder='Selecione...')=>`<option value="">${placeholder}</option>${arr.map(a=>`<option value="${E(a.id)}" ${String(val)===String(a.id)?'selected':''}>${E(a.name||a.title||a.description)}</option>`).join('')}`;
const option=(name,val,label,type='text',extras='')=>`<div class="field"><label for="f-${name}">${label}</label><input class="input" id="f-${name}" name="${name}" type="${type}" value="${E(val??'')}" ${extras}></div>`;
const selectField=(name,val,label,options)=>`<div class="field"><label for="f-${name}">${label}</label><select class="select" id="f-${name}" name="${name}">${options.map(([v,l])=>`<option value="${E(v)}" ${String(val)===String(v)?'selected':''}>${E(l)}</option>`).join('')}</select></div>`;
const header=(title,desc,btn='')=>`<div class="page-title"><div><h1>${E(title)}</h1><p>${E(desc)}</p></div>${btn}</div>`;
const cardTitle=(label,iconName,right='')=>`<div class="card-head"><h2>${ico(iconName)} ${E(label)}</h2>${right}</div>`;
const pstatus=s=>({Aprovado:'green',Enviado:'blue','Em análise':'orange',Perdido:'red','Em andamento':'green',Concluída:'green'}[s]||'');
const pill=s=>`<span class="pill ${pstatus(s)}">${E(s)}</span>`;
const stat=(icoName,label,value,color='')=>`<div class="card stat-card"><div class="stat-icon ${color}">${ico(icoName)}</div><div style="min-width:0"><div class="stat-label">${E(label)}</div><div class="stat-value">${E(value)}</div></div></div>`;
const empty=(title,desc,iconName='file')=>`<div class="section-blank">${ico(iconName)}<strong>${E(title)}</strong><div class="card-sub">${E(desc)}</div></div>`;
function notify(msg,err=false){document.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.textContent=msg;if(err)n.style.background='#bd3748';document.body.appendChild(n);setTimeout(()=>n.remove(),4200)}
async function api(url,method='GET',data){const r=await fetch('/api/'+url,{method,headers:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});let b=await r.json().catch(()=>({error:'Falha de comunicação'}));if(!r.ok)throw Error(b.error||`Erro ${r.status}`);return b}
async function refresh(){const [clients,projects,budgets,catalog,proposals,settings,dash]=await Promise.all(['clients','projects','budgets','catalog','proposals','settings','dashboard'].map(p=>api(p)));Object.assign(ST,{clients,projects,budgets,catalog,proposals,settings,dash});}
function currentPage(){const p=location.hash.slice(1).split('/');return p[0]||'dashboard'}
async function navigate(p){location.hash=p;await onRoute()}
async function onRoute(){if(!ST.auth.authenticated)return;const parts=location.hash.replace('#','').split('/');ST.page=parts[0]||'dashboard';if(ST.page==='orcamento'&&parts[1]){ST.budget=await api('budgets/'+Number(parts[1]));}if(ST.page==='cronograma'){ST.scheduleBudget=ST.scheduleBudget||ST.budgets[0]?.id||0;ST.budget=ST.scheduleBudget?await api('budgets/'+ST.scheduleBudget):null}if(ST.page==='propostas'){ST.proposalBudget=ST.proposalBudget||ST.budgets[0]?.id||0;ST.budget=ST.proposalBudget?await api('budgets/'+ST.proposalBudget):null}ST.menu=false;render();}
function themeChoice(){return localStorage.getItem('civolten-theme')||'auto'}
function setTheme(t){localStorage.setItem('civolten-theme',t);document.documentElement.dataset.theme=t==='auto'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):t;ST.themeMenu=false;render()}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',e=>{if(themeChoice()==='auto')document.documentElement.dataset.theme=e.matches?'dark':'light'});
function shell(content){const page=ST.page==='orcamento'?'orcamentos':ST.page;
 return `<div class="layout"><div class="menu-shade ${ST.menu?'show':''}" data-action="close-menu"></div><aside class="sidebar ${ST.menu?'open':''}"><div class="brand"><img class="logo" src="/assets/logo.png" alt="CIVOLTEN"/></div><nav class="nav">${NAV.map(([key,label,icon])=>`<a href="#${key}" class="nav-link ${page===key?'active':''}">${ico(icon)}${label}</a>`).join('')}</nav><div class="nav-btm"><div class="mini-company"><img src="/assets/icone.png" alt=""/><div><strong>CIVOLTEN</strong><br/>Sistema interno • v0.1</div></div></div></aside><div class="workarea"><header class="topbar"><div class="mobile-top"><button class="icon-btn" data-action="menu" aria-label="Abrir menu">${ico('menu')}</button><img class="logo" src="/assets/logo.png" alt="CIVOLTEN"/></div><div class="global-search">${ico('search')}<span>Clientes, obras, orçamentos e custos SIURB</span></div><div class="header-actions"><span class="muted text-sm" style="display:none">CIVOLTEN Engenharia</span><button class="icon-btn" data-action="theme-menu" title="Aparência" aria-label="Tema">${ico(document.documentElement.dataset.theme==='dark'?'moon':'sun')}</button><button class="icon-btn" data-action="notifications" aria-label="Notificações">${ico('bell')}</button><div class="user-chip"><div class="user-dot">${ico('users')}</div><span>Administrador</span></div><button class="icon-btn" data-action="logout" title="Sair">${ico('logout')}</button></div>${ST.themeMenu?`<div class="theme-menu">${[['auto','Automático','monitor'],['light','Claro','sun'],['dark','Escuro','moon']].map(([v,l,i])=>`<button class="theme-option ${themeChoice()===v?'active':''}" data-action="theme" data-value="${v}">${ico(i)} ${l}</button>`).join('')}</div>`:''}</header><main class="content">${window.CIVOLTEN_DEMO?`<div class="warn" role="alert" style="margin-bottom:16px"><strong>Modo demonstração:</strong> dados fictícios, salvos somente neste navegador. Não cadastre informações reais nem use esta versão para enviar propostas comerciais.</div>`:''}${content}</main></div><nav class="mobile-nav">${[['dashboard','Início','home'],['clientes','Clientes','users'],['orcamentos','Orçamentos','file'],['cronograma','Prazos','calendar'],['configuracoes','Mais','menu']].map(([p,l,i])=>`<a href="#${p}" class="${page===p?'active':''}">${ico(i)}${l}</a>`).join('')}</nav></div>`;
}
function renderAuth(){const setup=ST.auth.setupRequired;document.querySelector('#app').innerHTML=`<div class="login-page"><div class="card login-card"><img class="login-logo" src="/assets/logo.png" alt="CIVOLTEN"/><h1>${setup?'Configurar primeiro acesso':'Acessar sistema'}</h1><p>${setup?'Crie o administrador local. Os dados ficam salvos no banco de dados do computador em que o sistema estiver instalado.':'Digite suas credenciais para acessar os orçamentos e clientes.'}</p><form data-form="${setup?'setup':'login'}"><div class="field"><label>Usuário</label><input class="input" name="username" required autocomplete="username" placeholder="administrador"></div><div class="field"><label>Senha</label><input class="input" name="password" required type="password" ${setup?'minlength="10"':''} autocomplete="${setup?'new-password':'current-password'}" placeholder="${setup?'Mínimo de 10 caracteres':'Sua senha'}"></div><button class="btn btn-primary" style="width:100%;margin-top:8px" type="submit">${ico(setup?'shield':'logout')} ${setup?'Criar administrador':'Entrar'}</button></form><div class="card-sub" style="margin-top:19px;text-align:center">Acesso privado • Temas claro e escuro • Sem assinatura</div></div></div>`}
function render(){if(!ST.auth.authenticated)return renderAuth();let html='';switch(ST.page){case'dashboard':html=renderDashboard();break;case'clientes':html=renderClients();break;case'obras':html=renderProjects();break;case'orcamentos':html=renderBudgets();break;case'orcamento':html=renderBudgetDetail();break;case'siurb':html=renderCatalog();break;case'cronograma':html=renderSchedule();break;case'propostas':html=renderProposals();break;case'relatorios':html=renderReports();break;case'configuracoes':html=renderSettings();break;default:html=renderDashboard();}document.querySelector('#app').innerHTML=shell(html)}
function miniChart(){const records=ST.budgets.map(b=>({date:b.created_at?.slice(0,7),total:b.total||0}));const todayDate=new Date(),keys=[];for(let i=11;i>=0;i--){const d=new Date(todayDate.getFullYear(),todayDate.getMonth()-i,1);keys.push({k:d.toISOString().slice(0,7),label:d.toLocaleDateString('pt-BR',{month:'short'})})}const v=keys.map(m=>records.filter(x=>x.date===m.k).reduce((s,x)=>s+x.total,0));const max=Math.max(...v,1),coords=v.map((n,i)=>`${25+i*47.5},${160-(n/max)*130}`).join(' ');return `<svg viewBox="0 0 600 190" class="chart" role="img" aria-label="Total orçado nos últimos 12 meses"><line x1="24" x2="560" y1="160" y2="160" stroke="var(--border)"/>${[30,73,116,159].map(y=>`<line x1="24" x2="560" y1="${y}" y2="${y}" stroke="var(--border)"/>`).join('')}<polyline points="${coords}" stroke="var(--orange)" fill="none" stroke-width="3" stroke-linejoin="round"/>${v.map((n,i)=>`<circle cx="${25+i*47.5}" cy="${160-(n/max)*130}" r="3.5" fill="var(--orange)"/>`).join('')}${keys.map((m,i)=>`<text class="chart-label" x="${25+i*47.5}" y="181" text-anchor="middle">${E(m.label)}</text>`).join('')}</svg>`;}
function renderDashboard(){const d=ST.dash||{counts:{},budgets:[],pipeline:[]};const n=d.counts;return `${header('Dashboard','Visão geral dos orçamentos, clientes e oportunidades comerciais.',`<button class="btn btn-primary" data-action="new-budget">${ico('plus')} Novo orçamento</button>`)}<div class="grid kpis">${stat('file','Orçamentos ativos',n.active||0)}${stat('send','Propostas enviadas',n.sent||0,'blue')}${stat('hardhat','Obras em andamento',n.works||0,'green')}${stat('database','Valor em negociação',reais(n.negotiation||0))}</div><div class="grid two-col"><section class="card card-pad">${cardTitle('Pipeline comercial','filter')}<div class="pipeline">${d.pipeline.map(p=>`<div class="pipe-cell"><div class="muted text-sm">${E(p.status)}</div><div class="pipe-val">${p.count}</div><div class="progress"><b style="width:${ST.budgets.length?Math.max(3,p.count/ST.budgets.length*100):0}%"></b></div></div>`).join('')}</div></section><section class="card card-pad">${cardTitle('Evolução de orçamentos','chart','<span class="muted text-sm">12 meses</span>')}${miniChart()}</section></div><div class="split leftwide"><section class="card card-pad">${cardTitle('Orçamentos recentes','file',`<a class="link text-sm" href="#orcamentos">Ver todos ${ico('right')}</a>`)}${ST.budgets.length?budgetTable(ST.budgets.slice(0,6)):empty('Nenhum orçamento ainda','Cadastre um cliente e crie seu primeiro orçamento.')}</section><div class="grid" style="align-content:start"><section class="card card-pad">${cardTitle('Próximas etapas','calendar')}<div class="mini-list">${ST.budgets.slice(0,4).map(b=>`<div class="mini-row"><div><strong>${E(b.title)}</strong><span>${E(b.client_name)} • ${E(b.status)}</span></div><a class="link" href="#orcamento/${b.id}">${ico('right')}</a></div>`).join('')||'<p class="card-sub">Aparecerão aqui as propostas e seus respectivos status.</p>'}</div></section><section class="card card-pad">${cardTitle('Base de custos','database')}<strong>SIURB São Paulo</strong><div class="card-sub">Referência recomendada: julho/2026</div><div class="card-sub">${ST.catalog.filter(x=>x.source==='SIURB').length} serviços oficiais importados</div><div style="margin-top:12px"><a href="#siurb" class="btn btn-small">${ico('download')} Gerenciar composições</a></div></section></div></div>`}
function budgetTable(rows){return `<div class="table-wrap"><table class="table"><thead><tr><th>Código</th><th>Cliente / Obra</th><th>Valor</th><th>Status</th><th>Ação</th></tr></thead><tbody>${rows.map(b=>`<tr><td><strong>${E(b.code)}</strong></td><td><strong>${E(b.client_name)}</strong><br><span class="muted">${E(b.project_name||b.title)}</span></td><td class="money">${reais(b.total)}</td><td>${pill(b.status)}</td><td><a class="link" href="#orcamento/${b.id}" title="Abrir">${ico('right')}</a></td></tr>`).join('')}</tbody></table></div><div class="mobile-only">${rows.map(b=>`<a class="mobile-list-item" href="#orcamento/${b.id}"><div><strong>${E(b.code)}</strong> ${pill(b.status)}</div><div class="muted text-sm">${E(b.client_name)} • ${E(b.project_name||b.title)}</div><strong>${reais(b.total)}</strong></a>`).join('')}</div>`}
function renderClients(){return `${header('Clientes','Cadastro, relacionamento e histórico de contratantes.',`<button class="btn btn-primary" data-action="new-client">${ico('plus')} Novo cliente</button>`)}<div class="grid" style="grid-template-columns:repeat(2,1fr);margin-bottom:14px">${stat('users','Clientes cadastrados',ST.clients.length)}${stat('building','Clientes com obras',new Set(ST.projects.map(p=>p.client_id)).size,'blue')}</div><section class="card card-pad">${cardTitle('Lista de clientes','users')}<div class="search-row"><input id="clientSearch" class="input" placeholder="Buscar por nome, documento ou cidade..." value="${E(ST.search)}"/></div>${ST.clients.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Cliente</th><th>Documento</th><th>Contato</th><th>Cidade</th><th>Orçamentos</th><th>Status</th><th>Ações</th></tr></thead><tbody>${ST.clients.filter(c=>`${c.name} ${c.doc} ${c.city}`.toLowerCase().includes(ST.search.toLowerCase())).map(c=>`<tr><td><strong>${E(c.name)}</strong><br><span class="muted">${E(c.type)}</span></td><td>${E(c.doc||'—')}</td><td>${E(c.contact||'—')}<br><span class="muted">${E(c.phone)}</span></td><td>${E(c.city||'—')}</td><td>${ST.budgets.filter(b=>b.client_id===c.id).length}</td><td>${pill(c.status)}</td><td><button class="icon-btn" data-action="edit-client" data-id="${c.id}" title="Editar">${ico('edit')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum cliente cadastrado','Clique em Novo cliente para começar.','users')}</section>`}
function renderProjects(){return `${header('Obras','Cadastro de empreendimentos e acompanhamento do status.',`<button class="btn btn-primary" data-action="new-project">${ico('plus')} Nova obra</button>`)}<div class="grid kpis">${stat('hardhat','Total de obras',ST.projects.length)}${stat('chart','Em andamento',ST.projects.filter(p=>p.status==='Em andamento').length,'green')}${stat('calendar','Em planejamento',ST.projects.filter(p=>p.status==='Planejamento').length,'blue')}${stat('check','Concluídas',ST.projects.filter(p=>p.status==='Concluída').length)}</div><section class="card card-pad">${cardTitle('Empreendimentos','building')}${ST.projects.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Obra</th><th>Cliente</th><th>Tipo</th><th>Endereço</th><th>Status</th><th>Ações</th></tr></thead><tbody>${ST.projects.map(p=>`<tr><td><strong>${E(p.name)}</strong></td><td>${E(p.client_name)}</td><td>${E(p.type)}</td><td>${E(p.address||'—')}</td><td>${pill(p.status)}</td><td><button class="icon-btn" data-action="edit-project" data-id="${p.id}">${ico('edit')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma obra cadastrada','Crie uma obra vinculada a um cliente.','hardhat')}</section>`}
function renderBudgets(){return `${header('Orçamentos','Crie propostas, ajuste custos e acompanhe o andamento comercial.',`<button class="btn btn-primary" data-action="new-budget">${ico('plus')} Novo orçamento</button>`)}<div class="grid kpis">${stat('file','Total de orçamentos',ST.budgets.length)}${stat('database','Volume orçado',reais(ST.budgets.reduce((s,b)=>s+b.total,0)),'blue')}${stat('check','Aprovados',ST.budgets.filter(b=>b.status==='Aprovado').length,'green')}${stat('send','Enviados',ST.budgets.filter(b=>b.status==='Enviado').length)}</div><section class="card card-pad">${cardTitle('Todos os orçamentos','file')}${ST.budgets.length?budgetTable(ST.budgets):empty('Nenhum orçamento criado','A primeira etapa é cadastrar um cliente e iniciar um orçamento.')}</section>`}
function renderBudgetDetail(){const b=ST.budget;if(!b)return empty('Orçamento não encontrado','Verifique a lista de orçamentos.');return `${header(b.code,`${b.client_name} • ${b.project_name||b.title}`,`<div class="actions"><button class="btn" data-action="edit-budget" data-id="${b.id}">${ico('edit')} Parâmetros</button><button class="btn btn-primary" data-action="proposal-budget">${ico('file')} Proposta PDF</button></div>`)}<div class="grid kpis">${stat('database','Custo direto',reais(b.summary.cost))}${stat('chart',`BDI (${fmt(b.bdi)}%)`,reais(b.summary.bdiValue),'blue')}${stat('clock','Horas-homem',`${fmt(b.summary.laborHours)} h`,'green')}${stat('calendar','Prazo com segurança',`${b.totalDays} dias úteis`)}</div><div class="actions" style="margin-bottom:15px"><button class="btn btn-primary" data-action="add-item">${ico('plus')} Adicionar item</button><button class="btn" data-action="open-catalog">${ico('database')} Catálogo SIURB</button><button class="btn" data-action="view-schedule">${ico('calendar')} Cronograma</button><button class="btn" data-action="status-budget">${ico('edit')} ${E(b.status)}</button></div><div class="split"><section class="card card-pad">${cardTitle('Itens do orçamento','file')}<div class="notice" style="margin-bottom:12px">Coeficientes de mão de obra em <strong>horas-homem por unidade</strong>. Confira os coeficientes das composições oficiais antes de utilizar valores comercialmente.</div>${b.items.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Serviço / Código</th><th>Und.</th><th>Quantidade</th><th>Unitário</th><th>h-h/un</th><th>Subtotal</th><th>Ações</th></tr></thead><tbody>${b.summary.rows.map(item=>`<tr><td><strong>${E(item.description)}</strong><br><span class="muted">${E(item.code||'Serviço próprio')}</span></td><td>${E(item.unit)}</td><td>${fmt(item.qty)}</td><td>${reais(item.unit_cost)}</td><td>${fmt(item.hh_unit)}</td><td class="money">${reais(item.subtotal)}</td><td><div style="display:flex"><button class="icon-btn" data-action="edit-item" data-id="${item.id}">${ico('edit')}</button><button class="icon-btn" data-action="delete-item" data-id="${item.id}">${ico('trash')}</button></div></td></tr>`).join('')}</tbody></table></div><div class="mobile-only">${b.summary.rows.map(item=>`<div class="mobile-item-card"><div style="display:flex;justify-content:space-between;gap:8px"><strong>${E(item.description)}</strong><span class="muted text-sm">${E(item.code)}</span></div><div class="mobile-item-fields"><div><span>Quantidade</span><strong>${fmt(item.qty)} ${E(item.unit)}</strong></div><div><span>Unitário</span><strong>${reais(item.unit_cost)}</strong></div><div><span>Subtotal</span><strong>${reais(item.subtotal)}</strong></div></div><div class="actions" style="margin-top:12px"><button class="btn btn-small" data-action="edit-item" data-id="${item.id}">${ico('edit')} Editar</button><button class="btn btn-small btn-danger" data-action="delete-item" data-id="${item.id}">${ico('trash')} Excluir</button></div></div>`).join('')}</div>`:empty('Sem itens de orçamento','Adicione serviços manuais ou importe um serviço do catálogo SIURB.')}<div class="summary-line"><strong>Preço final com BDI</strong><strong class="text-lg" style="color:var(--orange)">${reais(b.summary.total)}</strong></div></section><div class="grid" style="align-content:start"><section class="card card-pad">${cardTitle('Resumo financeiro','chart')}<div class="summary-line"><span>Custo direto</span><strong>${reais(b.summary.cost)}</strong></div><div class="summary-line"><span>BDI (${fmt(b.bdi)}%)</span><strong>${reais(b.summary.bdiValue)}</strong></div><div class="summary-line summary-total"><span>Preço de venda</span><strong>${reais(b.summary.total)}</strong></div><div class="card-sub" style="margin-top:12px">BDI tratado como percentual composto sobre os custos unitários importados. Confira se tributos, encargos e outras parcelas já estão incluídos antes de ajustar.</div></section><section class="card card-pad">${cardTitle('Produtividade e prazo','clock')}<div class="summary-line"><span>Equipe</span><strong>${b.workers} trabalhadores</strong></div><div class="summary-line"><span>Capacidade/dia</span><strong>${fmt(b.capacityDay)} h-h</strong></div><div class="summary-line"><span>Prazo base</span><strong>${b.baseDays} dias úteis</strong></div><div class="summary-line"><span>Segurança (${fmt(b.safety_pct)}%)</span><strong>+ ${b.safetyDays} dias</strong></div><div class="summary-line"><span>Prazo final</span><strong>${b.totalDays} dias úteis</strong></div><div class="warn" style="margin-top:12px">Estimativa sequencial inicial. A versão avançada permitirá equipes por função e tarefas paralelas mediante dependências validadas.</div></section></div></div>`}
function renderCatalog(){const rows=ST.catalog.filter(x=>`${x.description} ${x.code}`.toLowerCase().includes(ST.search.toLowerCase()));return `${header('Composições SIURB','Biblioteca de custos e coeficientes com data-base e regime de desoneração.',`<div class="actions"><button class="btn" data-action="open-official">${ico('right')} Fonte oficial</button><button class="btn btn-primary" data-action="import-catalog">${ico('download')} Importar CSV</button></div>`)}<div class="grid kpis">${stat('database','Registros disponíveis',ST.catalog.length)}${stat('file','Itens SIURB',ST.catalog.filter(x=>x.source==='SIURB').length,'blue')}${stat('clock','Com coeficiente de h-h',ST.catalog.filter(x=>x.hh_per_unit>0).length,'green')}${stat('calendar','Data-base sugerida','jul/2026')}</div><div class="notice" style="margin-bottom:14px">As composições oficiais devem ser importadas a partir dos arquivos da Prefeitura de São Paulo. A referência jul/2026 é apenas informativa até o arquivo ser carregado. Não há preços oficiais fictícios no banco.</div><section class="card card-pad">${cardTitle('Catálogo de serviços','database')}<div class="search-row"><input class="input" id="catalogSearch" placeholder="Buscar por código ou descrição..." value="${E(ST.search)}"/><button class="btn" data-action="import-catalog">${ico('plus')} Importar</button></div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Código</th><th>Descrição</th><th>Unidade</th><th>Custo unit.</th><th>h-h/un.</th><th>Origem</th><th>Data-base</th><th>Regime</th></tr></thead><tbody>${rows.slice(0,200).map(x=>`<tr><td>${E(x.code)}</td><td><strong>${E(x.description)}</strong></td><td>${E(x.unit)}</td><td class="money">${reais(x.cost)}</td><td>${fmt(x.hh_per_unit)}</td><td>${pill(x.source)}</td><td>${E(x.reference_month)}</td><td>${E(x.regime)}</td></tr>`).join('')}</tbody></table></div>`:empty('Catálogo vazio','Importe uma planilha CSV normalizada para começar a utilizar os custos oficiais.','database')}</section>`}
function renderSchedule(){const b=ST.budget;let bar='';if(b){let progress=0;bar=b.tasks.map((t,i)=>{const left=b.totalDays?progress/b.totalDays*100:0,width=b.totalDays?t.durationDays/b.totalDays*100:0;progress+=t.durationDays;return `<div class="timeline-task"><div><strong>${i+1}. ${E(t.name)}</strong><div class="muted">${fmt(t.hours)} h-h • ${t.durationDays} dias úteis</div></div><div class="gantt-track"><div class="gantt-bar ${i%3===1?'blue':i%3===2?'green':''}" style="left:${left.toFixed(2)}%;width:${width.toFixed(2)}%" title="${E(t.name)} • ${dbr(t.start)} até ${dbr(t.end)}"></div></div></div>`}).join('');if(b.safetyDays)bar+=`<div class="timeline-task"><div><strong>Margem de segurança</strong><div class="muted">${b.safetyDays} dias úteis</div></div><div class="gantt-track"><div class="gantt-bar gray" style="left:${b.baseDays/b.totalDays*100}%;width:${b.safetyDays/b.totalDays*100}%"></div></div></div>`}
 return `${header('Cronograma da obra','Planejamento físico, produtividade e margem de segurança.',`<button class="btn" data-action="print-schedule">${ico('print')} Imprimir</button>`)}<div class="card card-pad" style="margin-bottom:15px"><div class="search-row"><label class="text-sm" style="min-width:90px;font-weight:700">Orçamento</label><select class="select" id="scheduleSelect">${sel(ST.scheduleBudget,ST.budgets.map(x=>({id:x.id,name:`${x.code} • ${x.title}`})),'Selecione um orçamento')}</select></div></div>${!b?`<section class="card">${empty('Sem cronograma','Crie um orçamento e inclua serviços para gerar o cronograma.','calendar')}</section>`:`<div class="grid kpis">${stat('clock','Prazo base',`${b.baseDays} dias úteis`)}${stat('shield','Margem de segurança',`${b.safetyDays} dias úteis`,'blue')}${stat('calendar','Entrega prevista',dbr(b.finish),'green')}${stat('database','Custo planejado',reais(b.summary.total))}</div><section class="card card-pad">${cardTitle('Cronograma físico da obra','calendar',`<span class="pill orange">${b.tasks.length} atividades</span>`)}<div class="timeline-shell"><div class="timeline-head"><span>Etapa / Recursos</span><span>Distribuição dos dias úteis (início → conclusão)</span></div>${bar||empty('Sem atividades','Adicione itens ao orçamento.')}</div><div class="timeline-note">Início: ${dbr(b.start)} • Entrega: ${dbr(b.finish)} • Equipe: ${b.workers} pessoas • ${b.workDays} dias/semana</div></section><div class="grid two-col" style="margin-top:15px"><section class="card card-pad">${cardTitle('Produtividade e equipes','users')}<div class="summary-line"><span>Horas-homem estimadas</span><strong>${fmt(b.summary.laborHours)} h-h</strong></div><div class="summary-line"><span>Capacidade diária</span><strong>${fmt(b.capacityDay)} h-h/dia</strong></div><div class="summary-line"><span>Eficiência</span><strong>${Math.round(b.efficiency*100)}%</strong></div><div class="summary-line"><span>Jornada</span><strong>${fmt(b.hours_day)} h/dia</strong></div></section><section class="card card-pad">${cardTitle('Premissas de planejamento','info')}<div class="warn">${E(b.methodology)} Não trate a soma de h-h como duração exata de obra: frentes simultâneas, especialidades, clima, suprimentos e precedências precisam de validação técnica.</div></section></div>`}`;}
function renderProposals(){let b=ST.budget;return `${header('Proposta comercial','Revise e imprima propostas profissionais da CIVOLTEN em PDF.',`<button class="btn btn-primary" data-action="generate-proposal" ${!b?'disabled':''}>${ico('print')} Gerar proposta PDF</button>`)}<div class="card card-pad" style="margin-bottom:15px"><div class="search-row"><label class="text-sm" style="font-weight:700">Orçamento</label><select id="proposalSelect" class="select">${sel(ST.proposalBudget,ST.budgets.map(x=>({id:x.id,name:`${x.code} • ${x.title}`})),'Selecione um orçamento')}</select></div></div>${b?`<div class="split leftwide"><div>${proposalHTML(b,ST.settings)}</div><section class="card card-pad" style="align-self:start">${cardTitle('Dados da proposta','file')}${!ST.settings.cnpj?'<div class="warn" style="margin-bottom:12px">Preencha o CNPJ e os dados comerciais em Configurações antes de enviar ao cliente.</div>':''}<div class="summary-line"><span>Cliente</span><strong>${E(b.client_name)}</strong></div><div class="summary-line"><span>Orçamento</span><strong>${E(b.code)}</strong></div><div class="summary-line"><span>Valor</span><strong>${reais(b.summary.total)}</strong></div><div class="summary-line"><span>Prazo previsto</span><strong>${b.totalDays} dias úteis</strong></div><div class="summary-line"><span>Validade</span><strong>${b.validity_days} dias</strong></div><button style="width:100%;margin-top:14px" class="btn btn-primary" data-action="generate-proposal">${ico('print')} Exportar como PDF</button><p class="card-sub">O botão abre a janela de impressão: escolha “Salvar como PDF”. A emissão cria um registro de versão com os valores atuais.</p></section></div>`:empty('Sem proposta disponível','Crie um orçamento com cliente e serviços para gerar uma proposta.')}<div class="card card-pad" style="margin-top:15px">${cardTitle('Histórico de propostas emitidas','file')}${ST.proposals.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Proposta</th><th>Orçamento</th><th>Cliente</th><th>Emitida em</th><th>Prévia</th></tr></thead><tbody>${ST.proposals.map(p=>`<tr><td><strong>${E(p.code)}</strong></td><td>${E(p.title)}</td><td>${E(p.client_name)}</td><td>${dbr(p.created_at)}</td><td><button class="btn btn-small" data-action="print-snapshot" data-id="${p.id}">${ico('print')} Abrir</button></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma versão emitida','Ao gerar PDF, uma versão imutável da proposta será registrada.')}</div>`}
function proposalHTML(b,settings){const summary=b.summary||{rows:[],total:0};return `<section class="pdf-page"><div class="pdf-head"><img src="/assets/logo.png" style="width:172px;max-height:70px;object-fit:contain;object-position:left center" alt="CIVOLTEN"/><div style="text-align:right;font-size:12px"><strong>PROPOSTA COMERCIAL</strong><br>${E(b.code)}<br>${dbr(today())}</div></div><h2>1. Apresentação</h2><p>${E(settings.proposalIntro||'Apresentamos nossa proposta comercial para execução dos serviços especificados.')}</p><div style="background:#f5f7f9;padding:12px;font-size:12px;display:grid;grid-template-columns:1fr 1fr;gap:10px"><div><strong>Cliente</strong><br>${E(b.client_name)}<br>${E(b.client_doc)}</div><div><strong>Obra</strong><br>${E(b.project_name||b.title)}<br>${E(b.project_address||'')}</div></div><h2>2. Escopo dos serviços</h2><p>Serviços e quantidades orçados conforme itens apresentados a seguir.</p><div class="table-wrap"><table class="table"><thead><tr><th>Serviço</th><th>Un.</th><th>Qtd.</th><th style="text-align:right">Valor</th></tr></thead><tbody>${(summary.rows||[]).map(i=>`<tr><td>${E(i.description)}</td><td>${E(i.unit)}</td><td>${fmt(i.qty)}</td><td class="money">${reais(i.subtotal*(1+(b.bdi||0)/100))}</td></tr>`).join('')}</tbody></table></div><div class="summary-line" style="background:#fff1e5;padding:13px;color:#d65d04;margin-top:10px"><strong>VALOR TOTAL DA PROPOSTA</strong><strong style="font-size:19px">${reais(summary.total)}</strong></div><h2>3. Cronograma resumido</h2><p>Prazo estimado: <strong>${b.totalDays||0} dias úteis</strong>, incluindo ${b.safetyDays||0} dias de margem de segurança. Início previsto: ${dbr(b.start)}. Conclusão estimada: ${dbr(b.finish)}.</p><h2>4. Condições comerciais</h2><p><strong>Pagamento:</strong> ${E(b.payment_terms||'A negociar')}<br><strong>Validade da proposta:</strong> ${b.validity_days||30} dias a contar da emissão.<br><strong>Garantia:</strong> ${E(settings.proposalWarranty||'Conforme contrato.')}<br><strong>Observações:</strong> ${E(b.notes||'Conforme escopo orçado.')}</p><div style="border-top:1px solid #e6e8ed;margin-top:30px;padding-top:10px;font-size:10px;color:#697489">${E(settings.company||'CIVOLTEN')} • ${E(settings.cnpj||'CNPJ não informado')} • ${E(settings.phone||'')} • ${E(settings.email||'')}</div></section>`}
function renderReports(){const total=ST.budgets.reduce((s,b)=>s+b.total,0),approved=ST.budgets.filter(b=>b.status==='Aprovado'),a=approved.reduce((s,b)=>s+b.total,0);return `${header('Relatórios','Indicadores comerciais e financeiros calculados a partir dos orçamentos cadastrados.')}<div class="grid kpis">${stat('database','Volume orçado',reais(total))}${stat('check','Valor aprovado',reais(a),'green')}${stat('chart','Taxa de aprovação',ST.budgets.length?`${Math.round(approved.length/ST.budgets.length*100)}%`:'0%','blue')}${stat('users','Clientes ativos',ST.clients.filter(c=>c.status==='Ativo').length)}</div><div class="grid two-col"><section class="card card-pad">${cardTitle('Evolução mensal','chart')}${miniChart()}</section><section class="card card-pad">${cardTitle('Status das propostas','filter')}<div class="pipeline">${(ST.dash?.pipeline||[]).map(p=>`<div class="pipe-cell"><span class="text-sm muted">${E(p.status)}</span><div class="pipe-val">${p.count}</div></div>`).join('')}</div></section></div>`}
function renderSettings(){return `${header('Configurações','Identidade da empresa, dados para propostas e aparência do sistema.')}<div class="split leftwide"><section class="card card-pad">${cardTitle('Dados da CIVOLTEN','building')}<form data-form="settings"><div class="fields">${option('company',ST.settings.company,'Razão social / Nome comercial')}${option('cnpj',ST.settings.cnpj,'CNPJ')}${option('email',ST.settings.email,'E-mail','email')}${option('phone',ST.settings.phone,'Telefone')}${option('address',ST.settings.address,'Endereço')}${option('footer',ST.settings.footer,'Frase no rodapé')}<div class="field span2"><label>Apresentação padrão da proposta</label><textarea class="textarea" name="proposalIntro">${E(ST.settings.proposalIntro)}</textarea></div><div class="field span2"><label>Garantia padrão</label><textarea class="textarea" name="proposalWarranty">${E(ST.settings.proposalWarranty)}</textarea></div></div><button class="btn btn-primary" type="submit">${ico('check')} Salvar configurações</button></form></section><div class="grid" style="align-content:start"><section class="card card-pad">${cardTitle('Aparência','sun')}<p class="card-sub">A preferência permanece salva neste navegador. No modo automático, segue o sistema do computador ou celular.</p>${[['auto','Automático (dispositivo)'],['light','Modo claro'],['dark','Modo escuro']].map(([v,label])=>`<label style="display:flex;align-items:center;gap:10px;padding:12px 0;font-size:13px"><input type="radio" name="theme-radio" value="${v}" ${themeChoice()===v?'checked':''}/> ${label}</label>`).join('')}</section><section class="card card-pad">${cardTitle('Banco de dados','database')}<p class="card-sub">Os dados ficam em <strong>data/civolten.sqlite</strong> no servidor local. Faça backup periódico desse arquivo após encerrar a aplicação.</p><button class="btn" data-action="backup-json">${ico('download')} Exportar dados em JSON</button><div class="warn" style="margin-top:12px">Uso local inicial. Antes de publicar na internet será necessário implantar HTTPS, backups automáticos e configurar a infraestrutura de produção.</div></section></div></div>`}
const modal=(title,body)=>{ST.modal=title;document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><h2>${E(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Fechar">${ico('plus')}</button></div>${body}</div></div>`)};
const closeModal=()=>{ST.modal='';document.getElementById('modal')?.remove()};
function openClient(c={}){modal(c.id?'Editar cliente':'Cadastrar cliente',`<form data-form="client" data-id="${c.id||''}"><div class="fields">${option('name',c.name,'Cliente / Razão social','text','required')}${selectField('type',c.type||'Pessoa jurídica','Tipo',[['Pessoa jurídica','Pessoa jurídica'],['Pessoa física','Pessoa física'],['Órgão público','Órgão público'],['Condomínio','Condomínio']])}${option('doc',c.doc,'CPF / CNPJ')}${option('contact',c.contact,'Responsável / Contato')}${option('phone',c.phone,'Telefone')}${option('email',c.email,'E-mail','email')}${option('address',c.address,'Endereço')}${option('city',c.city,'Cidade / UF')}${selectField('status',c.status||'Ativo','Status',[['Ativo','Ativo'],['Inativo','Inativo'],['Em negociação','Em negociação']])}</div><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">${ico('check')} Salvar cliente</button></div></form>`)}
function openProject(p={}){if(!ST.clients.length){notify('Cadastre um cliente antes de criar uma obra.',true);return}modal(p.id?'Editar obra':'Cadastrar obra',`<form data-form="project" data-id="${p.id||''}"><div class="fields"><div class="field"><label>Cliente *</label><select class="select" name="client_id" required>${sel(p.client_id,ST.clients)}</select></div>${option('name',p.name,'Nome da obra','text','required')}${option('type',p.type||'Obra','Tipo de obra')}${selectField('status',p.status||'Planejamento','Status',[['Planejamento','Planejamento'],['Em andamento','Em andamento'],['Concluída','Concluída'],['Suspensa','Suspensa']])}<div class="field span2"><label>Endereço da obra</label><input class="input" name="address" value="${E(p.address)}"></div><div class="field span2"><label>Observações</label><textarea class="textarea" name="notes">${E(p.notes)}</textarea></div></div><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">${ico('check')} Salvar obra</button></div></form>`)}
function openBudget(b={}){if(!ST.clients.length){notify('Cadastre um cliente antes de criar um orçamento.',true);return}modal(b.id?'Editar parâmetros do orçamento':'Novo orçamento',`<form data-form="budget" data-id="${b.id||''}"><div class="stepper"><div class="step active"><span>1</span> Dados gerais</div><div class="step"><span>2</span> Serviços</div><div class="step"><span>3</span> Prazo</div><div class="step"><span>4</span> Proposta</div></div><div class="fields"><div class="field"><label>Cliente *</label><select class="select" name="client_id" id="clientBudget" required>${sel(b.client_id,ST.clients)}</select></div><div class="field"><label>Obra vinculada (opcional)</label><select class="select" name="project_id" id="projectBudget">${sel(b.project_id,ST.projects.filter(p=>!b.client_id||p.client_id===b.client_id))}</select></div>${option('title',b.title,'Título / Descrição','text','required')}${selectField('status',b.status||'Rascunho','Status',[['Rascunho','Rascunho'],['Enviado','Enviado'],['Em análise','Em análise'],['Aprovado','Aprovado'],['Perdido','Perdido']])}${option('reference_month',b.reference_month||'2026-07','Data-base dos custos (AAAA-MM)')}${selectField('regime',b.regime||'Sem desoneração','Regime',[['Sem desoneração','Sem desoneração'],['Com desoneração','Com desoneração']])}${option('bdi',b.bdi??25,'BDI (%)','number','min="0" max="200" step="0.1"')}${option('safety_pct',b.safety_pct??15,'Margem de segurança (%)','number','min="0" max="100" step="1"')}${option('workers',b.workers??2,'Tamanho inicial da equipe','number','min="1" step="1"')}${option('hours_day',b.hours_day??8,'Horas trabalhadas por dia','number','min="1" max="24" step="0.5"')}${option('efficiency',b.efficiency??0.8,'Fator de eficiência (0,1 a 1)','number','min="0.1" max="1" step="0.05"')}${selectField('work_days_week',b.work_days_week??5,'Dias trabalhados por semana',[[5,'Segunda a sexta (5)'],[6,'Segunda a sábado (6)']])}${option('start_date',b.start_date||today(),'Início previsto','date')}${option('validity_days',b.validity_days??30,'Validade da proposta (dias)','number','min="1" max="365"')}${option('payment_terms',b.payment_terms||'A negociar','Condições de pagamento')}<div class="field span2"><label>Observações e restrições</label><textarea class="textarea" name="notes">${E(b.notes)}</textarea></div></div><div class="warn">Cronograma inicial conservador. Equipes por especialidade, trabalhos paralelos e dependências exigirão revisão antes de transformar a estimativa em prazo contratual.</div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Cancelar</button><button type="submit" class="btn btn-primary">${ico('check')} Salvar e continuar</button></div></form>`)}
function openItem(item={}){const entries=ST.catalog.map(c=>`<option value="${c.id}" ${c.id===item.catalog_id?'selected':''}>${E(c.code)} • ${E(c.description)} • ${E(c.source)} ${E(c.reference_month)}</option>`).join('');modal(item.id?'Editar item':'Adicionar item',`<form data-form="item" data-id="${item.id||''}"><div class="field" style="margin-bottom:15px"><label>Selecionar serviço do catálogo (opcional)</label><select class="select" id="catalogItem"><option value="">Serviço manual / informar abaixo</option>${entries}</select><span class="hint">Ao selecionar, os campos são preenchidos com o custo e coeficiente importados. A quantidade é definida por você.</span></div><div class="fields">${option('code',item.code,'Código do serviço')}${option('unit',item.unit||'un','Unidade (m², m³, un...)')}${'<div class="field span2"><label>Descrição do serviço *</label><input class="input" name="description" value="'+E(item.description||'')+'" required></div>'}${option('qty',item.qty??1,'Quantidade','number','required min="0" step="any"')}${option('unit_cost',item.unit_cost??0,'Custo unitário (R$)','number','required min="0" step="any"')}${option('hh_unit',item.hh_unit??0,'Horas-homem por unidade','number','min="0" step="any"')}${option('team',item.team,'Categoria / Equipe responsável')}${option('sort_order',item.sort_order??(ST.budget?.items?.length||0)+1,'Ordem do serviço','number','min="0"')}</div><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">${ico('check')} Salvar item</button></div></form>`)}
function openStatus(){const b=ST.budget;modal('Situação comercial',`<form data-form="status-budget"><p class="card-sub">Atualize o status de ${E(b.code)}. O acompanhamento comercial será refletido nos relatórios.</p>${selectField('status',b.status,'Status',[['Rascunho','Rascunho'],['Enviado','Enviado'],['Em análise','Em análise'],['Aprovado','Aprovado'],['Perdido','Perdido']])}<div class="form-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">Salvar status</button></div></form>`)}
function csvRows(s,delim){const records=[];let row=[],field='',quoted=false;for(let i=0;i<s.length;i++){const c=s[i];if(c==='"'&&quoted&&s[i+1]==='"'){field+='"';i++;continue}if(c==='"'){quoted=!quoted;continue}if(c===delim&&!quoted){row.push(field);field='';continue}if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&s[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))records.push(row);row=[];field='';continue}field+=c;}row.push(field);if(row.some(x=>x.trim()))records.push(row);return records;}
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
function brNumber(v){let s=String(v??'0').trim().replace(/[R$\s]/g,'');if(s.includes(',')&&s.includes('.'))s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');else if(s.includes(','))s=s.replace(',','.');const n=Number(s);return Number.isFinite(n)?Math.max(0,n):0}
async function importCSV(form){const file=form.querySelector('[name=csv]').files[0];if(!file)throw Error('Selecione um arquivo .csv');const s=await file.text();const first=s.split(/\r?\n/)[0]||'';const delim=(first.match(/;/g)||[]).length>=(first.match(/,/g)||[]).length?';':',';const rows=csvRows(s.replace(/^\uFEFF/,''),delim);if(rows.length<2)throw Error('CSV sem registros. Use a estrutura indicada no exemplo.');const headers=rows.shift().map(norm);const find=(...aliases)=>headers.findIndex(x=>aliases.some(a=>x===norm(a)));
 const ix={code:find('codigo','codigo siurb','code'),description:find('descricao','descrição','servico','serviço'),unit:find('unidade','un','unit'),cost:find('custo','custo unitario','preco','preco unitario','valor','cost'),hh_per_unit:find('hh_un','hh por unidade','hh_per_unit','horas homem por unidade','produtividade'),category:find('categoria','grupo')};if(ix.code<0||ix.description<0||ix.cost<0)throw Error('CSV exige colunas codigo, descricao e custo. Confira o modelo de importação.');
 const entries=rows.slice(0,3000).map(row=>({code:row[ix.code],description:row[ix.description],unit:ix.unit>=0?row[ix.unit]:'un',cost:brNumber(row[ix.cost]),hh_per_unit:ix.hh_per_unit>=0?brNumber(row[ix.hh_per_unit]):0,category:ix.category>=0?row[ix.category]:'Geral'})).filter(x=>x.code&&x.description);
 return api('catalog/import','POST',{entries,source:form.elements.namedItem("source").value,reference_month:form.elements.namedItem("reference_month").value,regime:form.elements.namedItem("regime").value});
}
function openImport(){modal('Importar catálogo de custos',`<form data-form="catalog-import"><p class="card-sub">Para preservar origem e rastreabilidade, exporte os dados oficiais selecionados para CSV com colunas normalizadas. Os arquivos da SIURB possuem formatos diferentes; confira os campos antes da importação.</p><div class="notice" style="margin:12px 0"><strong>Colunas obrigatórias:</strong> codigo; descricao; unidade; custo<br><strong>Opcionais:</strong> hh_un; categoria<br><strong>Separadores:</strong> ponto e vírgula ou vírgula.<br>Os coeficientes <strong>hh_un</strong> devem representar a soma de horas-homem por unidade, conferida a partir da composição.</div><div class="fields">${selectField('source','PRÓPRIA','Origem',[['SIURB','SIURB São Paulo'],['PRÓPRIA','Tabela própria']])}${option('reference_month','2026-07','Data-base (AAAA-MM)')}${selectField('regime','Sem desoneração','Regime',[['Sem desoneração','Sem desoneração'],['Com desoneração','Com desoneração'],['Próprio','Tabela própria']])}<div class="field"><label>Arquivo CSV</label><input class="input" type="file" name="csv" accept=".csv,text/csv" required></div></div><a class="link text-sm" href="/assets/modelo-importacao.csv" download>Baixar modelo CSV com dados fictícios</a><div class="warn" style="margin-top:12px">Não importe uma composição e seus insumos simultaneamente como itens de venda, pois isso pode duplicar o custo. Mantenha versões de tabelas separadas.</div><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">${ico('download')} Importar registros</button></div></form>`)}
function printDocument(w,b,settings,title='Proposta comercial'){if(!w){notify('O navegador bloqueou a nova janela. Permita pop-ups neste site.',true);return}const html=proposalHTML(b,settings);w.document.open();w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${E(title)} • CIVOLTEN</title><style>html,body{margin:0;font-family:Arial,sans-serif;color:#172137;font-size:12px}*,*:before,*:after{box-sizing:border-box}.pdf-page{width:100%;padding:26px 34px}.pdf-head{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #ef7411;padding-bottom:12px}.pdf-page h2{border-left:3px solid #ef7411;padding-left:10px;font-size:15px;margin-top:24px}.pdf-page p{line-height:1.65}.table{width:100%;border-collapse:collapse;font-size:11px}.table th{text-align:left;background:#f4f6f8}.table td,.table th{border-bottom:1px solid #e7ebf1;padding:9px 7px}.summary-line{display:flex;justify-content:space-between;gap:20px}.money{text-align:right;white-space:nowrap}.table-wrap{width:100%}@page{size:A4;margin:12mm}@media print{.pdf-page{padding:0}thead{display:table-header-group}tr{break-inside:avoid}h2{break-after:avoid}}</style></head><body>${html}<script>window.onload=()=>setTimeout(()=>window.print(),450)<\/script></body></html>`);w.document.close()}
async function printProposal(){const popup=window.open('','_blank');if(!popup){notify('Permita janelas para exportar PDF.',true);return}popup.document.write('<p style="font-family:Arial;padding:20px">Preparando a proposta…</p>');try{const snap=await api('proposals','POST',{budget_id:ST.budget.id});const b=JSON.parse(snap.content);printDocument(popup,b,b.company,snap.code);await refresh();render();notify(`Versão ${snap.code} registrada. Selecione Salvar como PDF na impressão.`)}catch(err){popup.close();notify(err.message,true)}}
async function printSnapshot(id){const popup=window.open('','_blank');if(!popup){notify('Permita janelas para abrir proposta.',true);return}try{const record=await api('proposals/'+id);const b=JSON.parse(record.content);printDocument(popup,b,b.company,record.code)}catch(err){popup.close();notify(err.message,true)}}
function handleClientProjectBudgetChange(e){if(e.target.id==='clientBudget'){const f=e.target.closest('form');const project=f.querySelector('#projectBudget');if(project)project.innerHTML=sel('',ST.projects.filter(x=>String(x.client_id)===e.target.value))}}
function handleCatalogItem(e){if(e.target.id!=='catalogItem')return;const x=ST.catalog.find(x=>String(x.id)===e.target.value);if(!x)return;const form=e.target.closest('form');for(const [k,v] of Object.entries({code:x.code,description:x.description,unit:x.unit,unit_cost:x.cost,hh_unit:x.hh_per_unit})){const t=form.querySelector(`[name="${k}"]`);if(t)t.value=v}form.dataset.catalogId=x.id;}
function formObject(form){return Object.fromEntries(new FormData(form).entries())}
async function submitForm(form){const type=form.dataset.form,b=formObject(form),id=form.dataset.id;switch(type){
case 'setup':await api('auth/setup','POST',b);ST.auth=await api('auth/status');renderAuth();notify('Administrador criado. Agora entre com seus dados.');return;
case 'login':await api('auth/login','POST',b);ST.auth=await api('auth/status');await refresh();await onRoute();notify('Bem-vindo ao CIVOLTEN.');return;
case 'client':await api('clients'+(id?'/'+id:''),id?'PUT':'POST',b);break;
case 'project':await api('projects'+(id?'/'+id:''),id?'PUT':'POST',b);break;
case 'budget':{const saved=await api('budgets'+(id?'/'+id:''),id?'PUT':'POST',b);closeModal();await refresh();await navigate('orcamento/'+saved.id);notify('Orçamento salvo. Adicione os serviços.');return;}
case 'item':{if(form.dataset.catalogId)b.catalog_id=form.dataset.catalogId;else if(ST.budget?.items?.find(x=>x.id===Number(id))?.catalog_id)b.catalog_id=ST.budget.items.find(x=>x.id===Number(id)).catalog_id;await api(`budgets/${ST.budget.id}/items${id?'/'+id:''}`,id?'PUT':'POST',b);ST.budget=await api(`budgets/${ST.budget.id}`);break;}
case 'catalog-import':{const res=await importCSV(form);closeModal();ST.search='';await refresh();render();notify(`${res.inserted} registros importados/atualizados.`);return;}
case 'status-budget':await api('budgets/'+ST.budget.id,'PUT',b);ST.budget=await api('budgets/'+ST.budget.id);break;
case 'settings':await api('settings','PUT',b);break;
}closeModal();await refresh();if(ST.page==='orcamento')ST.budget=await api('budgets/'+ST.budget.id);render();notify('Alterações salvas com sucesso.');}
async function actionClick(button){const action=button.dataset.action,id=Number(button.dataset.id),value=button.dataset.value;switch(action){
case'menu':ST.menu=!ST.menu;render();return;
case'close-menu':ST.menu=false;render();return;
case'theme-menu':ST.themeMenu=!ST.themeMenu;render();return;
case'theme':setTheme(value);return;
case'logout':await api('auth/logout','POST');ST.auth=await api('auth/status');renderAuth();return;
case'notifications':notify('As próximas ações aparecem no painel inicial.');return;
case'new-client':openClient();return;
case'edit-client':openClient(ST.clients.find(x=>x.id===id));return;
case'new-project':openProject();return;
case'edit-project':openProject(ST.projects.find(x=>x.id===id));return;
case'new-budget':openBudget();return;
case'edit-budget':openBudget(ST.budget);return;
case'add-item':openItem();return;
case'edit-item':openItem(ST.budget.items.find(x=>x.id===id));return;
case'delete-item':if(!confirm('Excluir este item do orçamento?'))return;await api(`budgets/${ST.budget.id}/items/${id}`,'DELETE');ST.budget=await api('budgets/'+ST.budget.id);await refresh();render();notify('Item excluído');return;
case'status-budget':openStatus();return;
case'import-catalog':openImport();return;
case'open-catalog':await navigate('siurb');return;
case'view-schedule':ST.scheduleBudget=ST.budget.id;await navigate('cronograma');return;
case'proposal-budget':ST.proposalBudget=ST.budget.id;await navigate('propostas');return;
case'open-official':window.open('https://prefeitura.sp.gov.br/web/obras/w/tabelas_de_custos/355179','_blank','noopener');return;
case'generate-proposal':await printProposal();return;
case'print-snapshot':await printSnapshot(id);return;
case'print-schedule':window.print();return;
case'close-modal':closeModal();return;
case'backup-json':{const file={exported_at:new Date().toISOString(),warning:'Exportação parcial de registros. Backup completo requer cópia segura do banco civolten.sqlite.',clients:ST.clients,projects:ST.projects,budgets:ST.budgets,catalog:ST.catalog,settings:ST.settings};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(file,null,2)],{type:'application/json'}));a.download=`civolten-exportacao-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);notify('Exportação JSON realizada. Não substitui o backup SQLite completo.');return;}
} }
let searchTimer;
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-action]');if(btn){e.preventDefault();try{await actionClick(btn)}catch(err){notify(err.message,true)}return}if(e.target.classList.contains('modal-backdrop'))closeModal()});
document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const button=form.querySelector('[type=submit]');if(button)button.disabled=true;try{await submitForm(form)}catch(err){notify(err.message,true)}finally{if(button)button.disabled=false}});
document.addEventListener('change',async e=>{handleClientProjectBudgetChange(e);handleCatalogItem(e);if(e.target.name==='theme-radio'){setTheme(e.target.value)}if(e.target.id==='scheduleSelect'){ST.scheduleBudget=Number(e.target.value);await onRoute()}if(e.target.id==='proposalSelect'){ST.proposalBudget=Number(e.target.value);await onRoute()}});
document.addEventListener('input',e=>{if(['clientSearch','catalogSearch'].includes(e.target.id)){const id=e.target.id,value=e.target.value,caret=e.target.selectionStart;ST.search=value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const newInput=document.getElementById(id);if(newInput){newInput.focus();newInput.setSelectionRange(caret,caret)}},160)}});
window.addEventListener('hashchange',()=>onRoute().catch(e=>notify(e.message,true)));
(async()=>{try{ST.auth=await api('auth/status');if(ST.auth.authenticated){await refresh();await onRoute()}else renderAuth()}catch(e){document.getElementById('app').innerHTML=`<div class="login-page"><div class="card card-pad"><h2>Não foi possível iniciar o CIVOLTEN</h2><p>${E(e.message)}</p><p class="card-sub">Verifique o servidor e tente novamente.</p></div></div>`}})();